cypress_script:
describe('ParaBank Login Functionality', () => {
  it('should log in with valid credentials', () => {
    cy.visit('https://parabank.parasoft.com/parabank/index.htm');
    cy.get('input[name="username"]').type('validUsername');
    cy.get('input[name="password"]').type('validPassword');
    cy.get('input[value="Log In"]').click();
    cy.url().should('not.eq', 'https://parabank.parasoft.com/parabank/index.htm');
  });

  it('should not log in with empty credentials', () => {
    cy.visit('https://parabank.parasoft.com/parabank/index.htm');
    cy.get('input[value="Log In"]').click();
    cy.url().should('eq', 'https://parabank.parasoft.com/parabank/index.htm');
    cy.get('h1').should('contain', 'Customer Login');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('ParaBank Login Functionality', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/index.htm');
    await page.fill('input[name="username"]', 'validUsername');
    await page.fill('input[name="password"]', 'validPassword');
    await page.click('input[value="Log In"]');
    await expect(page).toHaveURL(/^(?!.*index.htm).*/);
  });

  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/index.htm');
    await page.click('input[value="Log In"]');
    await expect(page).toHaveURL('https://parabank.parasoft.com/parabank/index.htm');
    await expect(page.locator('h1')).toContainText('Customer Login');
  });
});
